def env_lines(text):
    env = {}

    for raw_line in text.splitlines():
        line = raw_line.strip()

        if not line or line.startswith("#"):
            continue

        key, sep, value = line.partition("=")

        if not sep:
            raise ValueError("missing =")

        key = key.strip()
        value = value.strip()

        if not key:
            raise ValueError("empty key")

        env[key] = value

    return env
