from typing import Any, Dict, List

def reconcile(desired: Dict[str, Any], actual: Dict[str, Any]) -> Dict[str, List[str]]:
    return {
        "create": sorted(name for name in desired if name not in actual),
        "update": sorted(name for name in desired if name in actual and desired[name] != actual[name]),
        "delete": sorted(name for name in actual if name not in desired),
    }

def changed_paths(before, after):
    def join_path(parent, key):
        return f"{parent}.{key}" if parent else key

    def compare(parent, left, right):
        if left == right:
            return []

        if isinstance(left, dict) and isinstance(right, dict):
            paths = []
            for key in sorted(set(left.keys()) | set(right.keys())):
                path = join_path(parent, key)

                if key not in left or key not in right:
                    paths.append(path)
                else:
                    left_value = left[key]
                    right_value = right[key]

                    if left_value == right_value:
                        continue

                    if isinstance(left_value, dict) and isinstance(right_value, dict):
                        paths.extend(compare(path, left_value, right_value))
                    else:
                        paths.append(path)

            return paths

        if parent:
            return [parent]

        return []

    return sorted(set(compare("", before, after)))

def coalesce(intervals):
    normalized = []

    for interval in intervals:
        start, end = interval

        if start > end:
            raise ValueError("start cannot be greater than end")

        if start == end:
            continue

        normalized.append((start, end))

    if not normalized:
        return ()

    normalized.sort()

    merged = []
    start, end = normalized[0]

    for next_start, next_end in normalized[1:]:
        if next_start <= end:
            if next_end > end:
                end = next_end
        else:
            merged.append((start, end))
            start, end = next_start, next_end

    merged.append((start, end))

    return tuple(merged)

